-- Timestamps and audit.

do $$
declare
  name text;
begin
  foreach name in array array['vendors', 'work_orders', 'issues', 'inspection_templates', 'incidents',
                               'insurance_claims', 'vehicle_expenses'] loop
    execute format('drop trigger if exists %I on public.%I', name || '_updated_at', name);
    execute format('create trigger %I before update on public.%I for each row execute function public.set_updated_at()',
                   name || '_updated_at', name);
  end loop;
  foreach name in array array['vendors', 'work_orders', 'issues', 'inspections', 'incidents',
                               'insurance_claims', 'fuel_transactions', 'vehicle_expenses'] loop
    execute format('drop trigger if exists %I on public.%I', name || '_audit', name);
    execute format('create trigger %I after insert or update or delete on public.%I for each row execute function public.audit_row()',
                   name || '_audit', name);
  end loop;
end $$;

-- Row level security: read / write permission per area, always inside the user's organization.

do $$
declare
  spec text[];
  specs text[][] := array[
    ['vendors', 'maintenance.read', 'maintenance.write'],
    ['work_orders', 'maintenance.read', 'maintenance.write'],
    ['work_order_items', 'maintenance.read', 'maintenance.write'],
    ['issues', 'maintenance.read', 'maintenance.write'],
    ['inspection_templates', 'inspections.read', 'inspections.manage'],
    ['inspection_template_items', 'inspections.read', 'inspections.manage'],
    ['inspections', 'inspections.read', 'inspections.write'],
    ['inspection_items', 'inspections.read', 'inspections.write'],
    ['incidents', 'incidents.read', 'incidents.write'],
    ['incident_photos', 'incidents.read', 'incidents.write'],
    ['incident_parties', 'incidents.read', 'incidents.write'],
    ['insurance_claims', 'incidents.read', 'incidents.write'],
    ['fuel_transactions', 'costs.read', 'costs.write'],
    ['vehicle_expenses', 'costs.read', 'costs.write']
  ];
begin
  foreach spec slice 1 in array specs loop
    execute format('alter table public.%I enable row level security', spec[1]);
    execute format('drop policy if exists %I on public.%I', spec[1] || '_select', spec[1]);
    execute format(
      'create policy %I on public.%I for select using (org_id = public.current_org_id() and (public.has_permission(%L) or public.has_permission(%L)))',
      spec[1] || '_select', spec[1], spec[2], spec[3]);
    execute format('drop policy if exists %I on public.%I', spec[1] || '_write', spec[1]);
    execute format(
      'create policy %I on public.%I for all using (org_id = public.current_org_id() and public.has_permission(%L)) with check (org_id = public.current_org_id() and public.has_permission(%L))',
      spec[1] || '_write', spec[1], spec[3], spec[3]);
    execute format('grant select, insert, update, delete on public.%I to authenticated', spec[1]);
  end loop;
end $$;

-- Issues reported by inspections and drivers need inspections.write, not maintenance.write.
drop policy if exists issues_report on public.issues;
create policy issues_report on public.issues for insert
  with check (org_id = public.current_org_id() and source in ('inspection', 'driver')
              and public.has_permission('inspections.write'));

-- Files: one private bucket; the second folder decides which permission applies.
--   <org_id>/work-orders/..., <org_id>/incidents/..., <org_id>/inspections/..., <org_id>/expenses/...

insert into storage.buckets (id, name, public)
values ('fleet-files', 'fleet-files', false)
on conflict (id) do nothing;

create or replace function public.fleet_file_permission(p_name text, p_write boolean)
returns boolean
language sql
stable
security definer
set search_path to 'public'
as $$
  select (storage.foldername(p_name))[1] = public.current_org_id()::text
     and case (storage.foldername(p_name))[2]
           when 'work-orders' then public.has_permission(case when p_write then 'maintenance.write' else 'maintenance.read' end)
           when 'incidents' then public.has_permission(case when p_write then 'incidents.write' else 'incidents.read' end)
           when 'inspections' then public.has_permission(case when p_write then 'inspections.write' else 'inspections.read' end)
           when 'expenses' then public.has_permission(case when p_write then 'costs.write' else 'costs.read' end)
           else false
         end;
$$;

drop policy if exists fleet_files_read on storage.objects;
create policy fleet_files_read on storage.objects for select
  using (bucket_id = 'fleet-files' and (public.fleet_file_permission(name, false) or public.fleet_file_permission(name, true)));

drop policy if exists fleet_files_insert on storage.objects;
create policy fleet_files_insert on storage.objects for insert
  with check (bucket_id = 'fleet-files' and public.fleet_file_permission(name, true));

drop policy if exists fleet_files_update on storage.objects;
create policy fleet_files_update on storage.objects for update
  using (bucket_id = 'fleet-files' and public.fleet_file_permission(name, true));

drop policy if exists fleet_files_delete on storage.objects;
create policy fleet_files_delete on storage.objects for delete
  using (bucket_id = 'fleet-files' and public.fleet_file_permission(name, true));

-- Cost per vehicle and month (roadmap 4.2 TCO): fuel, maintenance, expenses.
create or replace view public.vehicle_monthly_costs
with (security_invoker = true) as
select org_id, vehicle_id, month, category, sum(amount) as amount
  from (
    select org_id, vehicle_id, date_trunc('month', occurred_at)::date as month, 'fuel' as category, total as amount
      from public.fuel_transactions where vehicle_id is not null
    union all
    select org_id, vehicle_id, date_trunc('month', coalesce(closed_at, opened_at))::date, 'maintenance', total_cost
      from public.work_orders where status = 'done'
    union all
    select org_id, vehicle_id, date_trunc('month', occurred_at)::date, category, amount
      from public.vehicle_expenses where vehicle_id is not null
  ) costs
 group by org_id, vehicle_id, month, category;

grant select on public.vehicle_monthly_costs to authenticated;

commit;

