-- viper fleet roadmap, stage 5 (expansions): points of interest, dispatch jobs with customer
-- tracking links, trailers and equipment without GPS, EV / temperature limits, API keys and
-- webhooks per organization. Additions only; idempotent. RLS through has_permission(), like
-- stages 2-4.

begin;

create extension if not exists pgcrypto;

-- 1. Permission keys.

insert into public.permissions (key, description) values
  ('poi.read', 'View points of interest and customer visits'),
  ('poi.write', 'Manage points of interest'),
  ('dispatch.read', 'View dispatch jobs'),
  ('dispatch.write', 'Create, assign and update dispatch jobs'),
  ('integrations.manage', 'Manage API keys and webhooks')
on conflict (key) do nothing;

insert into public.role_permissions (role, permission)
select role::public.app_role, permission
  from (values
    ('admin', 'poi.read'), ('admin', 'poi.write'),
    ('admin', 'dispatch.read'), ('admin', 'dispatch.write'),
    ('admin', 'integrations.manage'),
    ('manager', 'poi.read'), ('manager', 'poi.write'),
    ('manager', 'dispatch.read'), ('manager', 'dispatch.write'),
    ('dispatcher', 'poi.read'), ('dispatcher', 'poi.write'),
    ('dispatcher', 'dispatch.read'), ('dispatcher', 'dispatch.write'),
    ('viewer', 'poi.read'), ('viewer', 'dispatch.read'),
    ('driver', 'dispatch.read')
  ) as grants (role, permission)
on conflict do nothing;

-- 2. Trailers and equipment: a vehicles row without a Traccar device (roadmap 4.8).

alter table public.vehicles alter column traccar_device_id drop not null;

alter table public.vehicles
  add column if not exists asset_kind text not null default 'vehicle',
  add column if not exists attached_vehicle_id uuid references public.vehicles (id) on delete set null,
  add column if not exists serial_number text,
  -- EV and cold chain limits (roadmap 4.8); null = no alert.
  add column if not exists temp_min numeric,
  add column if not exists temp_max numeric,
  add column if not exists battery_min numeric;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'vehicles_asset_kind_check') then
    alter table public.vehicles add constraint vehicles_asset_kind_check
      check (asset_kind in ('vehicle', 'trailer', 'equipment'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'vehicles_attached_self_check') then
    alter table public.vehicles add constraint vehicles_attached_self_check
      check (attached_vehicle_id is null or attached_vehicle_id <> id);
  end if;
end $$;

-- 3. Points of interest: customers, depots, fuel stations, suppliers. Each may own a Traccar
--    circle geofence so arrivals and departures become customer visits.

create table if not exists public.pois (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.organizations (id) on delete cascade,
  name text not null,
  category text not null default 'customer'
    check (category in ('customer', 'depot', 'supplier', 'fuel', 'garage', 'other')),
  address text,
  latitude double precision,
  longitude double precision,
  radius_m integer not null default 100 check (radius_m between 10 and 5000),
  contact_name text,
  phone text,
  opening_hours text,
  notes text,
  traccar_geofence_id integer,
  active boolean not null default true,
  created_by uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (org_id, name)
);

create index if not exists pois_geofence_idx on public.pois (traccar_geofence_id);

-- 4. Dispatch jobs: deliveries, service calls and pickups for a vehicle and driver.

create table if not exists public.dispatch_jobs (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.organizations (id) on delete cascade,
  number bigint generated by default as identity,
  title text not null,
  type text not null default 'delivery'
    check (type in ('delivery', 'pickup', 'service', 'visit', 'other')),
  status text not null default 'planned'
    check (status in ('planned', 'assigned', 'en_route', 'arrived', 'done', 'failed', 'cancelled')),
  priority text not null default 'normal' check (priority in ('low', 'normal', 'high', 'urgent')),
  poi_id uuid references public.pois (id) on delete set null,
  customer_name text,
  customer_phone text,
  address text,
  latitude double precision,
  longitude double precision,
  vehicle_id uuid references public.vehicles (id) on delete set null,
  driver_id uuid references public.drivers (id) on delete set null,
  scheduled_at timestamptz,
  window_end timestamptz,
  started_at timestamptz,
  arrived_at timestamptz,
  completed_at timestamptz,
  proof_name text,
  proof_signature_path text,
  proof_photo_path text,
  tracking_link text,
  tracking_expires_at timestamptz,
  notes text,
  created_by uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists dispatch_jobs_day_idx on public.dispatch_jobs (org_id, scheduled_at);
create index if not exists dispatch_jobs_driver_idx on public.dispatch_jobs (driver_id, status);

-- Timestamps of the status changes are filled by the database.
create or replace function public.dispatch_job_status()
returns trigger
language plpgsql
set search_path to 'public'
as $$
begin
  if tg_op = 'INSERT' or new.status is distinct from old.status then
    if new.status = 'en_route' and new.started_at is null then
      new.started_at := now();
    elsif new.status = 'arrived' and new.arrived_at is null then
      new.arrived_at := now();
    elsif new.status in ('done', 'failed') and new.completed_at is null then
      new.completed_at := now();
    end if;
    if new.status = 'planned' and (new.vehicle_id is not null or new.driver_id is not null) then
      new.status := 'assigned';
    end if;
  end if;
  return new;
end;
$$;

drop trigger if exists dispatch_jobs_status on public.dispatch_jobs;
create trigger dispatch_jobs_status before insert or update on public.dispatch_jobs
  for each row execute function public.dispatch_job_status();

-- 5. API keys: only a SHA-256 hash is stored; the key is shown once when created.

create table if not exists public.api_keys (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.organizations (id) on delete cascade,
  name text not null,
  prefix text not null,
  key_hash text not null unique,
  scopes text[] not null default array['read'],
  last_used_at timestamptz,
  expires_at timestamptz,
  revoked_at timestamptz,
  created_by uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now()
);

-- For the public API gateway (service role only): the organization and scopes of a valid key.
create or replace function public.api_key_lookup(p_key text)
returns table (org_id uuid, scopes text[])
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  found public.api_keys;
begin
  select * into found from public.api_keys k
   where k.key_hash = encode(sha256(convert_to(p_key, 'UTF8')), 'hex')
     and k.revoked_at is null and (k.expires_at is null or k.expires_at > now());
  if found.id is null then
    return;
  end if;
  update public.api_keys set last_used_at = now() where id = found.id;
  return query select found.org_id, found.scopes;
end;
$$;

revoke all on function public.api_key_lookup(text) from public, anon, authenticated;

-- 6. Webhooks: events are queued in webhook_deliveries by triggers and sent by a pg_cron job
--    with an HMAC-SHA256 signature; retries back off exponentially, at most 5 attempts.

create table if not exists public.webhooks (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.organizations (id) on delete cascade,
  name text not null,
  url text not null check (url ~ '^https://'),
  events text[] not null default '{}',
  secret text not null default replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', ''),
  active boolean not null default true,
  created_by uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.webhook_deliveries (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.organizations (id) on delete cascade,
  webhook_id uuid not null references public.webhooks (id) on delete cascade,
  event text not null,
  payload jsonb not null,
  status text not null default 'queued' check (status in ('queued', 'sending', 'sent', 'failed')),
  attempts integer not null default 0,
  next_attempt_at timestamptz not null default now(),
  request_id bigint,
  response_code integer,
  error text,
  created_at timestamptz not null default now(),
  sent_at timestamptz
);

create index if not exists webhook_deliveries_due_idx on public.webhook_deliveries (next_attempt_at)
  where status in ('queued', 'sending');

-- Event names: <table>.<insert|update|status>, e.g. dispatch_jobs.status, incidents.insert.
create or replace function public.queue_webhooks()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  event_name text;
  row_data jsonb := to_jsonb(new);
begin
  if tg_op = 'INSERT' then
    event_name := tg_table_name || '.insert';
  elsif row_data ? 'status' and (to_jsonb(old) ->> 'status') is distinct from (row_data ->> 'status') then
    event_name := tg_table_name || '.status';
  else
    event_name := tg_table_name || '.update';
  end if;
  insert into public.webhook_deliveries (org_id, webhook_id, event, payload)
  select w.org_id, w.id, event_name,
         jsonb_build_object('event', event_name, 'occurred_at', now(), 'data', row_data)
    from public.webhooks w
   where w.active and w.org_id = new.org_id
     and (event_name = any (w.events) or (tg_table_name || '.*') = any (w.events));
  return null;
end;
$$;

do $$
declare
  name text;
begin
  foreach name in array array['dispatch_jobs', 'incidents', 'work_orders', 'issues', 'inspections',
                               'document_alerts', 'driver_violations'] loop
    if to_regclass('public.' || name) is not null then
      execute format('drop trigger if exists %I on public.%I', name || '_webhooks', name);
      execute format('create trigger %I after insert or update on public.%I for each row execute function public.queue_webhooks()',
                     name || '_webhooks', name);
    end if;
  end loop;
end $$;

-- Sender: needs pg_net (bundled with Supabase). Without it deliveries stay queued.
create or replace function public.send_webhooks()
returns integer
language plpgsql
security definer
set search_path to 'public', 'extensions'
as $$
declare
  delivery record;
  body text;
  sent integer := 0;
begin
  if not exists (select 1 from pg_extension where extname = 'pg_net') then
    return 0;
  end if;

  -- Collect answers of the previous run.
  update public.webhook_deliveries d
     set status = case when r.status_code between 200 and 299 then 'sent'
                       when d.attempts >= 5 then 'failed' else 'queued' end,
         response_code = r.status_code,
         error = left(r.error_msg, 500),
         sent_at = case when r.status_code between 200 and 299 then now() end,
         next_attempt_at = now() + make_interval(mins => power(2, d.attempts)::int)
    from net._http_response r
   where d.status = 'sending' and r.id = d.request_id;

  for delivery in
    select d.*, w.url, w.secret from public.webhook_deliveries d
      join public.webhooks w on w.id = d.webhook_id
     where d.status = 'queued' and d.next_attempt_at <= now() and w.active
     order by d.next_attempt_at
     limit 100
     for update of d skip locked
  loop
    body := delivery.payload::text;
    update public.webhook_deliveries
       set status = 'sending',
           attempts = attempts + 1,
           request_id = net.http_post(
             url := delivery.url,
             body := delivery.payload,
             headers := jsonb_build_object(
               'Content-Type', 'application/json',
               'X-ViperFleet-Event', delivery.event,
               'X-ViperFleet-Delivery', delivery.id::text,
               'X-ViperFleet-Signature',
               'sha256=' || encode(hmac(body, delivery.secret, 'sha256'), 'hex')),
             timeout_milliseconds := 10000)
     where id = delivery.id;
    sent := sent + 1;
  end loop;
  return sent;
end;
$$;

revoke all on function public.send_webhooks() from public, anon, authenticated;

select cron.unschedule(jobid) from cron.job where jobname = 'vf_send_webhooks';
select cron.schedule('vf_send_webhooks', '* * * * *', 'select public.send_webhooks()');

-- 7. Timestamps and audit.

do $$
declare
  name text;
begin
  foreach name in array array['pois', 'dispatch_jobs', 'webhooks'] loop
    execute format('drop trigger if exists %I on public.%I', name || '_updated_at', name);
    execute format('create trigger %I before update on public.%I for each row execute function public.set_updated_at()',
                   name || '_updated_at', name);
  end loop;
  foreach name in array array['pois', 'dispatch_jobs', 'webhooks'] loop
    execute format('drop trigger if exists %I on public.%I', name || '_audit', name);
    execute format('create trigger %I after insert or update or delete on public.%I for each row execute function public.audit_row()',
                   name || '_audit', name);
  end loop;
end $$;

-- API keys: not on every use (last_used_at), only when created, renamed, re-scoped or revoked.
drop trigger if exists api_keys_audit on public.api_keys;
create trigger api_keys_audit after insert or delete or update of name, scopes, expires_at, revoked_at
  on public.api_keys for each row execute function public.audit_row();

-- 8. Row level security.

do $$
declare
  spec text[];
  specs text[][] := array[
    ['pois', 'poi.read', 'poi.write'],
    ['api_keys', 'integrations.manage', 'integrations.manage'],
    ['webhooks', 'integrations.manage', 'integrations.manage'],
    ['webhook_deliveries', 'integrations.manage', 'integrations.manage']
  ];
begin
  foreach spec slice 1 in array specs loop
    execute format('alter table public.%I enable row level security', spec[1]);
    execute format('drop policy if exists %I on public.%I', spec[1] || '_select', spec[1]);
    execute format(
      'create policy %I on public.%I for select using (org_id = public.current_org_id() and (public.has_permission(%L) or public.has_permission(%L)))',
      spec[1] || '_select', spec[1], spec[2], spec[3]);
    execute format('drop policy if exists %I on public.%I', spec[1] || '_write', spec[1]);
    execute format(
      'create policy %I on public.%I for all using (org_id = public.current_org_id() and public.has_permission(%L)) with check (org_id = public.current_org_id() and public.has_permission(%L))',
      spec[1] || '_write', spec[1], spec[3], spec[3]);
    execute format('grant select, insert, update, delete on public.%I to authenticated', spec[1]);
  end loop;
end $$;

-- Dispatch: a driver sees only their own jobs and may move them along (status, proof).
alter table public.dispatch_jobs enable row level security;

drop policy if exists dispatch_jobs_select on public.dispatch_jobs;
create policy dispatch_jobs_select on public.dispatch_jobs for select
  using (org_id = public.current_org_id()
         and (public.has_permission('dispatch.read') or public.has_permission('dispatch.write'))
         and (not public.is_driver_role() or driver_id = public.my_driver_id()));

drop policy if exists dispatch_jobs_write on public.dispatch_jobs;
create policy dispatch_jobs_write on public.dispatch_jobs for all
  using (org_id = public.current_org_id() and public.has_permission('dispatch.write')
         and not public.is_driver_role())
  with check (org_id = public.current_org_id() and public.has_permission('dispatch.write')
              and not public.is_driver_role());

drop policy if exists dispatch_jobs_driver_update on public.dispatch_jobs;
create policy dispatch_jobs_driver_update on public.dispatch_jobs for update
  using (org_id = public.current_org_id() and public.is_driver_role()
         and driver_id = public.my_driver_id())
  with check (org_id = public.current_org_id() and driver_id = public.my_driver_id()
              and status in ('en_route', 'arrived', 'done', 'failed'));

grant select, insert, update, delete on public.dispatch_jobs to authenticated;

-- 9. Files: proof of delivery under <org_id>/dispatch/... in the fleet-files bucket.

create or replace function public.fleet_file_permission(p_name text, p_write boolean)
returns boolean
language sql
stable
security definer
set search_path to 'public'
as $$
  select (storage.foldername(p_name))[1] = public.current_org_id()::text
     and case (storage.foldername(p_name))[2]
           when 'work-orders' then public.has_permission(case when p_write then 'maintenance.write' else 'maintenance.read' end)
           when 'incidents' then public.has_permission(case when p_write then 'incidents.write' else 'incidents.read' end)
           when 'inspections' then public.has_permission(case when p_write then 'inspections.write' else 'inspections.read' end)
           when 'expenses' then public.has_permission(case when p_write then 'costs.write' else 'costs.read' end)
           when 'safety' then public.has_permission(case when p_write then 'safety.write' else 'safety.read' end)
           when 'dispatch' then public.has_permission('dispatch.read') or public.has_permission('dispatch.write')
           else false
         end;
$$;

commit;

