-- ─── 20261113100000_client_metrics.sql
select exists (select 1 from vf_meta.ui_migrations where name = '20261113100000_client_metrics.sql') as vf_done \gset
\if :vf_done
\echo 'Already applied: 20261113100000_client_metrics.sql'
\else
\echo 'Applying: 20261113100000_client_metrics.sql'
-- viper fleet: what the browser measures (FND-06). Idempotent.
--
-- The UI sends a batch every few minutes and when the page is hidden (src/common/telemetry):
-- web vitals (LCP, INP, CLS, FCP, TTFB), long tasks, and operational counters such as socket
-- disconnects, fleet-token failures, chunk-load errors and Supabase error codes.
--
--   client_metrics        one row per measurement, with the release, the environment, the screen
--                         as a template ("/settings/device/:id") and the organization; never the
--                         user. Kept 30 days.
--   client_metrics_usage  rows accepted per user and hour, so no one can fill the table
--   record_client_metrics(release, environment, batch)   the only way in; checks every value
--   client_metrics_overview(days)                         per release and metric: p75, share
--                                                         rated good, totals; platform admins only

begin;

create table if not exists public.client_metrics (
  id bigint generated always as identity primary key,
  recorded_at timestamptz not null default now(),
  org_id uuid references public.organizations (id) on delete cascade,
  release text not null,
  environment text not null,
  kind text not null check (kind in ('vital', 'counter', 'longtask')),
  name text not null,
  route text,
  value double precision not null,
  rating text check (rating in ('good', 'needs-improvement', 'poor'))
);

comment on table public.client_metrics is
  'Browser measurements (FND-06): web vitals, long tasks and counters. Nothing personal; 30 days.';

create index if not exists client_metrics_time_idx on public.client_metrics (recorded_at desc);

create table if not exists public.client_metrics_usage (
  user_id uuid not null,
  hour timestamptz not null,
  count integer not null default 0,
  primary key (user_id, hour)
);

alter table public.client_metrics enable row level security;
alter table public.client_metrics_usage enable row level security;

-- Read through client_metrics_overview only; written through record_client_metrics only.
revoke all on public.client_metrics from anon, authenticated;
revoke all on public.client_metrics_usage from anon, authenticated;

-- A JSON number as a double, null for anything else.
create or replace function public.client_metric_number(p_value jsonb)
returns double precision
language sql
immutable
as $$
  select case when jsonb_typeof(p_value) = 'number' then (p_value)::double precision end
$$;

-- Returns the number of rows kept. Values outside the rules are skipped, not an error: an old tab
-- must never get stuck on a batch.
create or replace function public.record_client_metrics(
  p_release text,
  p_environment text,
  p_metrics jsonb
)
returns integer
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  v_user uuid := auth.uid();
  v_org uuid := public.current_org_id();
  v_hour timestamptz := date_trunc('hour', now());
  v_used integer;
  v_room integer;
  v_rows integer := 0;
  v_counters jsonb;
  v_vitals jsonb;
  v_long jsonb;
begin
  if v_user is null then
    raise exception 'sign in first' using errcode = '42501';
  end if;
  if p_release is null or p_release !~ '^[0-9A-Za-z.+_-]{1,40}$'
     or p_environment is null or p_environment not in ('production', 'staging', 'development', 'demo')
     or jsonb_typeof(p_metrics) is distinct from 'object' then
    raise exception 'not a metrics batch' using errcode = '22023';
  end if;

  select coalesce(sum(count), 0) into v_used
    from public.client_metrics_usage where user_id = v_user and hour = v_hour;
  -- 500 rows an hour per user: a busy session sends a few dozen.
  v_room := 500 - v_used;
  if v_room <= 0 then
    return 0;
  end if;

  v_counters := case when jsonb_typeof(p_metrics->'counters') = 'object'
                     then p_metrics->'counters' else '{}'::jsonb end;
  -- Only objects: value->'value' on anything else is null and the row is skipped.
  v_vitals := case when jsonb_typeof(p_metrics->'vitals') = 'array'
                   then p_metrics->'vitals' else '[]'::jsonb end;
  v_long := case when jsonb_typeof(p_metrics->'longtasks') = 'object'
                 then p_metrics->'longtasks' else '{}'::jsonb end;

  -- Every number goes through public.client_metric_number, which is null for anything else, so a
  -- string where a number belongs is skipped instead of failing the cast.
  insert into public.client_metrics (org_id, release, environment, kind, name, route, value, rating)
  select v_org, p_release, p_environment, b.kind, b.name, b.route, b.value, b.rating
    from (
      select 'counter'::text as kind, c.key as name, null::text as route, c.num as value,
             null::text as rating
        from (select key, public.client_metric_number(value) as num
                from jsonb_each(v_counters) limit 50) c
       where c.key ~ '^[a-z][a-z0-9_.]{0,59}$' and c.num between 1 and 100000
      union all
      select 'vital', s.v->>'name', s.v->>'route', s.num, s.v->>'rating'
        from (select value as v, public.client_metric_number(value->'value') as num
                from jsonb_array_elements(v_vitals) limit 100) s
       where s.v->>'name' in ('LCP', 'INP', 'CLS', 'FCP', 'TTFB')
         and s.num between 0 and 600000
         and (s.v->>'route' is null or s.v->>'route' ~ '^/[A-Za-z0-9/_:.-]{0,119}$')
         and (s.v->>'rating' is null or s.v->>'rating' in ('good', 'needs-improvement', 'poor'))
      union all
      select 'longtask', l.name, null, public.client_metric_number(v_long->l.name), null
        from (values ('count', 1, 100000), ('total_ms', 0, 86400000), ('max_ms', 0, 86400000))
             as l (name, low, high)
       where public.client_metric_number(v_long->'count') >= 1
         and public.client_metric_number(v_long->l.name) between l.low and l.high
      limit v_room
    ) b;
  get diagnostics v_rows = row_count;

  if v_rows > 0 then
    insert into public.client_metrics_usage as u (user_id, hour, count)
    values (v_user, v_hour, v_rows)
    on conflict (user_id, hour) do update set count = u.count + excluded.count;
  end if;
  return v_rows;
end;
$$;

-- Per release and metric over the last p_days days (1 to 90). Vitals: p75 and the share rated
-- "good"; counters and long tasks: the total and the largest single value; and how many
-- organizations reported it.
create or replace function public.client_metrics_overview(p_days integer default 7)
returns table (
  release text,
  kind text,
  name text,
  samples bigint,
  total double precision,
  p75 double precision,
  good double precision,
  maximum double precision,
  orgs bigint,
  last_at timestamptz
)
language plpgsql
stable
security definer
set search_path to 'public'
as $$
begin
  if not public.is_platform_admin() then
    raise exception 'platform administrators only' using errcode = '42501';
  end if;
  return query
    select m.release, m.kind, m.name,
           count(*),
           sum(m.value),
           case when m.kind = 'vital'
                then percentile_cont(0.75) within group (order by m.value) end,
           case when m.kind = 'vital'
                then avg(case when m.rating = 'good' then 1.0 else 0.0 end)::double precision end,
           max(m.value),
           count(distinct m.org_id),
           max(m.recorded_at)
      from public.client_metrics m
     where m.recorded_at > now() - make_interval(days => greatest(1, least(coalesce(p_days, 7), 90)))
     group by m.release, m.kind, m.name
     order by max(m.recorded_at) desc, m.kind, m.name;
end;
$$;

create or replace function public.client_metrics_cleanup()
returns void
language sql
security definer
set search_path to 'public'
as $$
  delete from public.client_metrics where recorded_at < now() - interval '30 days';
  delete from public.client_metrics_usage where hour < now() - interval '1 day';
$$;

revoke all on function public.record_client_metrics(text, text, jsonb) from public, anon;
revoke all on function public.client_metrics_overview(integer) from public, anon;
revoke all on function public.client_metrics_cleanup() from public, anon, authenticated;
grant execute on function public.record_client_metrics(text, text, jsonb) to authenticated;
grant execute on function public.client_metrics_overview(integer) to authenticated;

do $$
begin
  perform cron.unschedule(jobid) from cron.job where jobname = 'vf_client_metrics_cleanup';
  perform cron.schedule('vf_client_metrics_cleanup', '40 3 * * *', 'select public.client_metrics_cleanup();');
end $$;

commit;

insert into vf_meta.ui_migrations (name) values ('20261113100000_client_metrics.sql') on conflict do nothing;
\endif

-- ─── 20261114100000_role_guard.sql
select exists (select 1 from vf_meta.ui_migrations where name = '20261114100000_role_guard.sql') as vf_done \gset
\if :vf_done
\echo 'Already applied: 20261114100000_role_guard.sql'
\else
\echo 'Applying: 20261114100000_role_guard.sql'
-- viper fleet: roles and permission overrides are guarded in the database (SEC-08). Idempotent.
--
-- The rules lived only in the interface ("you cannot edit yourself", "only an owner touches an
-- owner"), while the browser writes profiles.role and user_permissions directly. Whatever the row
-- policies on the server say, these triggers now refuse, for a signed-in user:
--
--   profiles          changing your own role, organization or access; moving anyone to another
--                     organization; touching a profile of another organization; making or
--                     unmaking an owner unless you are an owner; any role or access change
--                     without users.manage
--   user_permissions  overrides for yourself, for another organization, or for an owner unless
--                     you are an owner; platform keys (customers.*, billing.*); anything without
--                     users.manage
--
-- Platform administrators and server-side code (the service role, migrations: no auth.uid())
-- are not limited. Every role, organization or access change, and every override, is written
-- to audit_log.

begin;

-- The signed-in user's own profile; empty for the service role.
create or replace function public.role_guard_actor()
returns table (id uuid, org_id uuid, role public.app_role)
language sql
stable
security definer
set search_path to 'public'
as $$
  select p.id, p.org_id, p.role from public.profiles p where p.id = auth.uid() and p.is_active
$$;

revoke all on function public.role_guard_actor() from public, anon;

create or replace function public.guard_profile_change()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  actor record;
  target public.profiles := coalesce(new, old);
begin
  if auth.uid() is null or public.is_platform_admin() then
    return coalesce(new, old);
  end if;
  select * into actor from public.role_guard_actor();
  if actor.id is null then
    raise exception 'no active profile' using errcode = '42501';
  end if;

  if tg_op = 'UPDATE' then
    -- Name, last seen and the like: anyone the row policies allow. The rest is guarded.
    if new.role is not distinct from old.role
       and new.org_id is not distinct from old.org_id
       and new.is_active is not distinct from old.is_active then
      return new;
    end if;
    if old.id = actor.id then
      raise exception 'you cannot change your own role, organization or access'
        using errcode = '42501';
    end if;
    if new.org_id is distinct from old.org_id then
      raise exception 'users cannot be moved to another organization' using errcode = '42501';
    end if;
  elsif tg_op = 'DELETE' and old.id = actor.id then
    raise exception 'you cannot remove yourself' using errcode = '42501';
  end if;

  if target.org_id is distinct from actor.org_id then
    raise exception 'that user is in another organization' using errcode = '42501';
  end if;
  if (coalesce(new.role::text, '') = 'owner' or coalesce(old.role::text, '') = 'owner')
     and actor.role <> 'owner' then
    raise exception 'only an owner can make, change or remove an owner' using errcode = '42501';
  end if;
  if not public.has_permission('users.manage') then
    raise exception 'users.manage is required' using errcode = '42501';
  end if;
  return coalesce(new, old);
end;
$$;

drop trigger if exists profiles_role_guard on public.profiles;
create trigger profiles_role_guard before insert or update or delete on public.profiles
  for each row execute function public.guard_profile_change();

-- Role, organization and access changes go to the audit log (not every "last seen").
create or replace function public.audit_profile_access()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $$
begin
  if tg_op = 'UPDATE'
     and new.role is not distinct from old.role
     and new.org_id is not distinct from old.org_id
     and new.is_active is not distinct from old.is_active then
    return null;
  end if;
  insert into public.audit_log (org_id, user_id, action, table_name, row_id, old_data, new_data)
  values (coalesce(new.org_id, old.org_id), auth.uid(), lower(tg_op), 'profiles',
          coalesce(new.id, old.id)::text,
          case when tg_op <> 'INSERT'
               then jsonb_build_object('role', old.role, 'org_id', old.org_id, 'is_active', old.is_active) end,
          case when tg_op <> 'DELETE'
               then jsonb_build_object('role', new.role, 'org_id', new.org_id, 'is_active', new.is_active) end);
  return null;
end;
$$;

drop trigger if exists profiles_access_audit on public.profiles;
create trigger profiles_access_audit after insert or update or delete on public.profiles
  for each row execute function public.audit_profile_access();

create or replace function public.guard_user_permission()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  actor record;
  target public.profiles;
  rec public.user_permissions := coalesce(new, old);
begin
  if auth.uid() is null or public.is_platform_admin() then
    return coalesce(new, old);
  end if;
  select * into actor from public.role_guard_actor();
  select * into target from public.profiles where id = rec.user_id;
  if actor.id is null then
    raise exception 'no active profile' using errcode = '42501';
  end if;
  if tg_op = 'UPDATE' and new.user_id is distinct from old.user_id then
    raise exception 'an override cannot move to another user' using errcode = '42501';
  end if;
  if rec.user_id = actor.id then
    raise exception 'you cannot change your own permissions' using errcode = '42501';
  end if;
  if target.id is null or target.org_id is distinct from actor.org_id then
    raise exception 'that user is in another organization' using errcode = '42501';
  end if;
  if target.role = 'owner' and actor.role <> 'owner' then
    raise exception 'only an owner can change an owner''s permissions' using errcode = '42501';
  end if;
  if rec.permission like 'customers.%' or rec.permission like 'billing.%' then
    raise exception 'platform permissions are not granted per user' using errcode = '42501';
  end if;
  if not public.has_permission('users.manage') then
    raise exception 'users.manage is required' using errcode = '42501';
  end if;
  return coalesce(new, old);
end;
$$;

drop trigger if exists user_permissions_guard on public.user_permissions;
create trigger user_permissions_guard before insert or update or delete on public.user_permissions
  for each row execute function public.guard_user_permission();

create or replace function public.audit_user_permission()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  rec public.user_permissions := coalesce(new, old);
begin
  insert into public.audit_log (org_id, user_id, action, table_name, row_id, old_data, new_data)
  values ((select org_id from public.profiles where id = rec.user_id), auth.uid(), lower(tg_op),
          'user_permissions', rec.user_id || ':' || rec.permission,
          case when tg_op <> 'INSERT' then to_jsonb(old) end,
          case when tg_op <> 'DELETE' then to_jsonb(new) end);
  return null;
end;
$$;

drop trigger if exists user_permissions_audit on public.user_permissions;
create trigger user_permissions_audit after insert or update or delete on public.user_permissions
  for each row execute function public.audit_user_permission();

commit;

insert into vf_meta.ui_migrations (name) values ('20261114100000_role_guard.sql') on conflict do nothing;
\endif

-- ─── 20261114110000_billing_integrity.sql
select exists (select 1 from vf_meta.ui_migrations where name = '20261114110000_billing_integrity.sql') as vf_done \gset
\if :vf_done
\echo 'Already applied: 20261114110000_billing_integrity.sql'
\else
\echo 'Applying: 20261114110000_billing_integrity.sql'
-- viper fleet: billing integrity (SEC-09). Idempotent.
--
-- "Edit only while a draft" was enforced by the interface only; saving a bill deleted and
-- re-inserted its lines in separate requests (a failure in between left a partial bill); the
-- number could be set by hand; and nothing in the platform tables was audited. Now:
--
--   - a bill's number always comes from the sequence, and never changes
--   - once a bill is not a draft, only its status, payment details and notes change; it never goes
--     back to draft; its lines are locked; it is cancelled, not deleted
--   - billing_save_invoice(invoice, lines) saves a bill and replaces its lines in one transaction
--   - every change to customers, their users, the device registry, plans, subscriptions, bills
--     and bill lines goes to audit_log
--
-- Server-side code (the billing-documents edge function, migrations) is not limited.

begin;

create or replace function public.billing_is_service()
returns boolean
language sql
stable
as $$
  select coalesce(current_setting('request.jwt.claim.role', true), '') = 'service_role'
      or current_user in ('service_role', 'postgres', 'supabase_admin')
$$;

-- ─── bills ───────────────────────────────────────────────────────────────────

create or replace function public.billing_invoice_guard()
returns trigger
language plpgsql
as $$
declare
  -- What may change on a bill that is no longer a draft. The official document fields are
  -- guarded on their own (billing_official_guard: the provider only, or releasing a stuck claim).
  open_fields text[] := array['status', 'paid_at', 'payment_method', 'payment_reference', 'notes',
                              'updated_at', 'subtotal', 'vat_amount', 'total',
                              'official_state', 'official_type', 'official_id', 'official_number',
                              'official_url', 'official_amount', 'official_issued_at',
                              'official_error', 'receipt_state', 'receipt_id', 'receipt_number',
                              'receipt_url', 'payment_url', 'payment_token'];
begin
  if tg_op = 'INSERT' then
    new.number := nextval('public.billing_invoice_number_seq');
    return new;
  end if;
  if new.number is distinct from old.number then
    raise exception 'a bill keeps its number' using errcode = '42501';
  end if;
  if public.billing_is_service() then
    return new;
  end if;
  if old.status <> 'draft' then
    if new.status = 'draft' then
      raise exception 'an issued bill does not go back to draft' using errcode = '42501';
    end if;
    if (to_jsonb(new) - open_fields) is distinct from (to_jsonb(old) - open_fields) then
      raise exception 'an issued bill changes only its status, payment and notes; cancel it and issue a new one'
        using errcode = '42501';
    end if;
  end if;
  return new;
end;
$$;

drop trigger if exists billing_invoice_guard on public.billing_invoices;
create trigger billing_invoice_guard before insert or update on public.billing_invoices
  for each row execute function public.billing_invoice_guard();

create or replace function public.billing_invoice_delete_draft_only()
returns trigger
language plpgsql
as $$
begin
  if old.status <> 'draft' and not public.billing_is_service() then
    raise exception 'an issued bill is cancelled, not deleted' using errcode = '42501';
  end if;
  return old;
end;
$$;

drop trigger if exists billing_invoice_delete_draft_only on public.billing_invoices;
create trigger billing_invoice_delete_draft_only before delete on public.billing_invoices
  for each row execute function public.billing_invoice_delete_draft_only();

create or replace function public.billing_lines_draft_only()
returns trigger
language plpgsql
as $$
declare
  v_status text;
begin
  select status into v_status from public.billing_invoices
   where id = coalesce(new.invoice_id, old.invoice_id);
  -- No parent: the bill itself is being deleted (only a draft can be).
  if v_status is not null and v_status <> 'draft' and not public.billing_is_service() then
    raise exception 'the lines of an issued bill cannot change' using errcode = '42501';
  end if;
  return coalesce(new, old);
end;
$$;

drop trigger if exists billing_lines_draft_only on public.billing_invoice_lines;
create trigger billing_lines_draft_only before insert or update or delete on public.billing_invoice_lines
  for each row execute function public.billing_lines_draft_only();

-- One transaction for a bill and its lines. p_lines null keeps the lines. The lines are replaced
-- while the bill is still a draft, and the requested status is set last, so "issue" works in one
-- call. Runs with the caller's rights: row security (billing.manage) applies.
create or replace function public.billing_save_invoice(p_invoice jsonb, p_lines jsonb default null)
returns uuid
language plpgsql
security invoker
set search_path to 'public'
as $$
declare
  v_id uuid := nullif(p_invoice->>'id', '')::uuid;
  v_status text := coalesce(p_invoice->>'status', 'draft');
  v_current text;
  has text[] := array(select jsonb_object_keys(p_invoice));
begin
  if v_status not in ('draft', 'issued', 'paid', 'cancelled') then
    raise exception 'unknown status' using errcode = '22023';
  end if;
  if v_id is null then
    insert into public.billing_invoices
      (customer_id, issue_date, due_date, period_start, period_end, vat_rate,
       payment_method, payment_reference, notes, status)
    values ((p_invoice->>'customer_id')::uuid,
            coalesce((p_invoice->>'issue_date')::date, current_date),
            coalesce((p_invoice->>'due_date')::date, current_date + 30),
            (p_invoice->>'period_start')::date, (p_invoice->>'period_end')::date,
            coalesce((p_invoice->>'vat_rate')::numeric, 18),
            p_invoice->>'payment_method', p_invoice->>'payment_reference', p_invoice->>'notes',
            'draft')
    returning id into v_id;
    v_current := 'draft';
  else
    select status into v_current from public.billing_invoices where id = v_id for update;
    if v_current is null then
      raise exception 'no such bill' using errcode = 'P0002';
    end if;
  end if;

  if p_lines is not null then
    if v_current <> 'draft' then
      raise exception 'the lines of an issued bill cannot change' using errcode = '42501';
    end if;
    delete from public.billing_invoice_lines where invoice_id = v_id;
    insert into public.billing_invoice_lines (invoice_id, description, quantity, unit_price, sort_order)
    select v_id, line->>'description', coalesce((line->>'quantity')::numeric, 0),
           coalesce((line->>'unit_price')::numeric, 0), (ordinality - 1)::integer
      from jsonb_array_elements(p_lines) with ordinality as l(line, ordinality)
     where coalesce(trim(line->>'description'), '') <> '';
  end if;

  update public.billing_invoices i set
    customer_id = case when 'customer_id' = any (has) then (p_invoice->>'customer_id')::uuid else i.customer_id end,
    issue_date = case when 'issue_date' = any (has) then (p_invoice->>'issue_date')::date else i.issue_date end,
    due_date = case when 'due_date' = any (has) then (p_invoice->>'due_date')::date else i.due_date end,
    period_start = case when 'period_start' = any (has) then (p_invoice->>'period_start')::date else i.period_start end,
    period_end = case when 'period_end' = any (has) then (p_invoice->>'period_end')::date else i.period_end end,
    vat_rate = case when 'vat_rate' = any (has) then (p_invoice->>'vat_rate')::numeric else i.vat_rate end,
    payment_method = case when 'payment_method' = any (has) then p_invoice->>'payment_method' else i.payment_method end,
    payment_reference = case when 'payment_reference' = any (has) then p_invoice->>'payment_reference' else i.payment_reference end,
    notes = case when 'notes' = any (has) then p_invoice->>'notes' else i.notes end,
    status = case when 'status' = any (has) then v_status else i.status end
  where i.id = v_id
    -- Untouched fields of an issued bill are not "changed": write only what differs.
    and (v_current = 'draft' or 'status' = any (has) or 'notes' = any (has)
         or 'payment_method' = any (has) or 'payment_reference' = any (has));
  return v_id;
end;
$$;

revoke all on function public.billing_save_invoice(jsonb, jsonb) from public, anon;
grant execute on function public.billing_save_invoice(jsonb, jsonb) to authenticated;

-- ─── audit ───────────────────────────────────────────────────────────────────

-- Platform tables have no org_id, and some no id column: the row is named by its key.
create or replace function public.audit_platform_row()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  rec jsonb := to_jsonb(coalesce(new, old));
begin
  insert into public.audit_log (org_id, user_id, action, table_name, row_id, old_data, new_data)
  values (null, auth.uid(), lower(tg_op), tg_table_name,
          coalesce(rec->>'id', rec->>'traccar_device_id', rec->>'traccar_user_id'),
          case when tg_op <> 'INSERT' then to_jsonb(old) end,
          case when tg_op <> 'DELETE' then to_jsonb(new) end);
  return null;
end;
$$;

do $$
declare
  t text;
begin
  foreach t in array array['customers', 'customer_users', 'device_registry', 'billing_plans',
                           'billing_subscriptions', 'billing_invoices', 'billing_invoice_lines']
  loop
    execute format('drop trigger if exists %I on public.%I', t || '_audit', t);
    execute format('create trigger %I after insert or update or delete on public.%I '
                   'for each row execute function public.audit_platform_row()', t || '_audit', t);
  end loop;
end $$;

commit;

