\endif

-- ─── 20261114120000_privacy_rights.sql
select exists (select 1 from vf_meta.ui_migrations where name = '20261114120000_privacy_rights.sql') as vf_done \gset
\if :vf_done
\echo 'Already applied: 20261114120000_privacy_rights.sql'
\else
\echo 'Applying: 20261114120000_privacy_rights.sql'
-- viper fleet: employees' privacy rights (SEC-12, on top of ISR-03's privacy migration). Idempotent.
--
--   - Turning "private" on stops the customer tracking links of that driver's and vehicle's open
--     jobs at once (a link would otherwise keep showing where the car is).
--   - privacy_subject_export(driver): everything the fleet database keeps about one employee, for
--     a request to see one's data. Recorded in the view log.
--   - privacy_erase_driver(driver): when an employee leaves and the organization must not keep
--     their personal details: the name, ID number, phone, e-mail, licence and notes are erased,
--     their documents are deleted (the files' paths are returned for the app to delete from
--     storage), the full copies in the audit log are reduced to "erased", and a linked user
--     profile loses its name (switching the user off stays in user management). Records the organization must keep (incidents,
--     tickets, inspections) stay, attached to the anonymous driver.
--
-- Both need privacy.manage and work in the caller's organization only.

begin;

alter table public.drivers add column if not exists erased_at timestamptz;
alter table public.profiles add column if not exists erased_at timestamptz;

-- ─── private periods stop tracking links ────────────────────────────────────

create or replace function public.privacy_private_close_links()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $$
begin
  update public.dispatch_jobs
     set tracking_link = null,
         tracking_expires_at = least(coalesce(tracking_expires_at, now()), now())
   where org_id = new.org_id
     and tracking_link is not null
     and status not in ('done', 'failed', 'cancelled')
     and ((new.driver_id is not null and driver_id = new.driver_id)
          or (new.vehicle_id is not null and vehicle_id = new.vehicle_id));
  return null;
end;
$$;

drop trigger if exists privacy_private_close_links on public.privacy_private_periods;
create trigger privacy_private_close_links after insert on public.privacy_private_periods
  for each row execute function public.privacy_private_close_links();

-- ─── the employee's data ────────────────────────────────────────────────────

create or replace function public.privacy_driver_of_org(p_driver uuid)
returns public.drivers
language plpgsql
stable
security definer
set search_path to 'public'
as $$
declare
  v public.drivers;
begin
  if not public.has_permission('privacy.manage') then
    raise exception 'privacy.manage is required' using errcode = '42501';
  end if;
  select * into v from public.drivers where id = p_driver and org_id = public.current_org_id();
  if v.id is null then
    raise exception 'no such driver in this organization' using errcode = 'P0002';
  end if;
  return v;
end;
$$;

-- Tables that point at a driver (a driver_id column), found in the schema, so a new table is
-- covered without changing this function.
create or replace function public.privacy_driver_tables()
returns setof text
language sql
stable
as $$
  select c.table_name::text
    from information_schema.columns c
    join information_schema.tables t
      on t.table_schema = c.table_schema and t.table_name = c.table_name
   where c.table_schema = 'public' and c.column_name = 'driver_id' and t.table_type = 'BASE TABLE'
   order by 1
$$;

create or replace function public.privacy_subject_export(p_driver uuid)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  v_driver public.drivers := public.privacy_driver_of_org(p_driver);
  v_result jsonb;
  v_rows jsonb;
  v_table text;
begin
  v_result := jsonb_build_object(
    'exported_at', now(),
    'driver', to_jsonb(v_driver),
    'profile', (select to_jsonb(p) from public.profiles p where p.id = v_driver.profile_id),
    'records', '{}'::jsonb);
  for v_table in select public.privacy_driver_tables() loop
    execute format('select coalesce(jsonb_agg(to_jsonb(t)), ''[]'') from public.%I t where t.driver_id = $1',
                   v_table)
      into v_rows using p_driver;
    if jsonb_array_length(v_rows) > 0 then
      v_result := jsonb_set(v_result, array['records', v_table], v_rows);
    end if;
  end loop;
  insert into public.privacy_view_log (org_id, profile_id, traccar_device_ids, view)
  values (v_driver.org_id, auth.uid(), '{}', 'export');
  return v_result;
end;
$$;

-- Returns { files: [{ bucket, path }], tables: { name: rows } }.
create or replace function public.privacy_erase_driver(p_driver uuid)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  v_driver public.drivers := public.privacy_driver_of_org(p_driver);
  v_files jsonb := '[]';
  v_paths jsonb;
  v_table text;
  v_column text;
  v_count integer;
  v_counts jsonb := '{}';
begin
  -- Files of the driver's own documents (bucket "documents") and of other driver records
  -- (bucket "fleet-files"), for the app to delete from storage.
  select coalesce(jsonb_agg(jsonb_build_object('bucket', 'documents', 'path', storage_path)), '[]')
    into v_files from public.documents where driver_id = p_driver and storage_path is not null;
  for v_table, v_column in
    select c.table_name, c.column_name from information_schema.columns c
     where c.table_schema = 'public' and c.column_name like '%path'
       and c.table_name in (select public.privacy_driver_tables()) and c.table_name <> 'documents'
  loop
    execute format('select coalesce(jsonb_agg(jsonb_build_object(''bucket'', ''fleet-files'', ''path'', t.%I)), ''[]'')
                      from public.%I t where t.driver_id = $1 and t.%I is not null', v_column, v_table, v_column)
      into v_paths using p_driver;
    v_files := v_files || v_paths;
  end loop;

  delete from public.documents where driver_id = p_driver;
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('documents', v_count);

  update public.drivers
     set full_name = 'נהג שנמחק', national_id = null, phone = null, email = null,
         license_number = null, notes = null, traccar_driver_id = null, erased_at = now()
   where id = p_driver;

  -- The audit log kept full copies of the row; keep that something changed, not what.
  update public.audit_log
     set old_data = case when old_data is null then null else '{"erased": true}'::jsonb end,
         new_data = case when new_data is null then null else '{"erased": true}'::jsonb end
   where (table_name = 'drivers' and row_id = p_driver::text)
      or old_data->>'driver_id' = p_driver::text
      or new_data->>'driver_id' = p_driver::text;
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('audit_log', v_count);

  if v_driver.profile_id is not null then
    -- The name only: switching the user off stays a user-management action (SEC-08).
    update public.profiles set full_name = null, erased_at = now() where id = v_driver.profile_id;
  end if;

  insert into public.audit_log (org_id, user_id, action, table_name, row_id, new_data)
  values (v_driver.org_id, auth.uid(), 'update', 'drivers', p_driver::text,
          jsonb_build_object('erased', true, 'files', jsonb_array_length(v_files)));
  return jsonb_build_object('files', v_files, 'tables', v_counts);
end;
$$;

revoke all on function public.privacy_driver_of_org(uuid) from public, anon;
revoke all on function public.privacy_subject_export(uuid) from public, anon;
revoke all on function public.privacy_erase_driver(uuid) from public, anon;
grant execute on function public.privacy_subject_export(uuid) to authenticated;
grant execute on function public.privacy_erase_driver(uuid) to authenticated;

commit;

insert into vf_meta.ui_migrations (name) values ('20261114120000_privacy_rights.sql') on conflict do nothing;
\endif

-- ─── 20261114130000_fleet_save.sql
select exists (select 1 from vf_meta.ui_migrations where name = '20261114130000_fleet_save.sql') as vf_done \gset
\if :vf_done
\echo 'Already applied: 20261114130000_fleet_save.sql'
\else
\echo 'Applying: 20261114130000_fleet_save.sql'
-- viper fleet: saves that span several tables happen in one transaction (ARC-05). Idempotent.
--
-- The browser used to write a parent row, then delete its child rows and insert them again in
-- separate requests: a dropped connection in between left a work order without lines, an
-- incident without its parties, a checklist without items. Now one call does it all, or nothing:
--
--   fleet_save(kind, id, row, children, single)
--     kind      'work_order'           work_orders, lines in work_order_items
--               'incident'             incidents, parties in incident_parties, the claim in
--                                      insurance_claims (single)
--               'inspection_template'  inspection_templates, items in inspection_template_items
--     id        null to insert, else the row to update
--     row       the parent's columns (only real, writable columns are used)
--     children  null keeps them; else the full list, replacing the old ones (org_id, the parent
--               link and sort_order are filled in)
--     single    the incident's claim: inserted, or updated by its id; null leaves it
--
-- Runs with the caller's rights: row security decides, as for the direct writes. (Bills have
-- their own function, billing_save_invoice, SEC-09.)

begin;

-- The columns of a table that a save may write: real, not generated, not the id.
create or replace function public.fleet_save_columns(p_table text, p_row jsonb)
returns text[]
language sql
stable
as $$
  select coalesce(array_agg(c.column_name::text order by c.ordinal_position), '{}')
    from information_schema.columns c
   where c.table_schema = 'public' and c.table_name = p_table
     and c.is_generated = 'NEVER' and c.column_name <> 'id'
     and p_row ? c.column_name
$$;

create or replace function public.fleet_save_insert(p_table text, p_row jsonb)
returns uuid
language plpgsql
security invoker
set search_path to 'public'
as $$
declare
  v_columns text[] := public.fleet_save_columns(p_table, p_row);
  v_list text;
  v_id uuid;
begin
  if p_table not in ('work_orders', 'work_order_items', 'incidents', 'incident_parties',
                     'insurance_claims', 'inspection_templates', 'inspection_template_items') then
    raise exception 'not a table fleet_save writes' using errcode = '42501';
  end if;
  select string_agg(quote_ident(c), ', ') into v_list from unnest(v_columns) c;
  execute format('insert into public.%I (%s) select %s from jsonb_populate_record(null::public.%I, $1) returning id',
                 p_table, v_list, v_list, p_table)
    into v_id using p_row;
  return v_id;
end;
$$;

create or replace function public.fleet_save_update(p_table text, p_id uuid, p_row jsonb)
returns void
language plpgsql
security invoker
set search_path to 'public'
as $$
declare
  v_columns text[] := public.fleet_save_columns(p_table, p_row);
  v_list text;
  v_found boolean;
begin
  if p_table not in ('work_orders', 'work_order_items', 'incidents', 'incident_parties',
                     'insurance_claims', 'inspection_templates', 'inspection_template_items') then
    raise exception 'not a table fleet_save writes' using errcode = '42501';
  end if;
  if cardinality(v_columns) = 0 then
    execute format('select exists (select 1 from public.%I where id = $1)', p_table) into v_found using p_id;
  else
    select string_agg(quote_ident(c), ', ') into v_list from unnest(v_columns) c;
    execute format('update public.%I t set (%s) = (select %s from jsonb_populate_record(null::public.%I, $1)) where t.id = $2',
                   p_table, v_list, v_list, p_table)
      using p_row, p_id;
    get diagnostics v_found = row_count;
  end if;
  if not v_found then
    raise exception 'no such row, or no permission to change it' using errcode = '42501';
  end if;
end;
$$;

create or replace function public.fleet_save(
  p_kind text,
  p_id uuid,
  p_row jsonb,
  p_children jsonb default null,
  p_single jsonb default null
)
returns uuid
language plpgsql
security invoker
set search_path to 'public'
as $$
declare
  v_parent text;
  v_child text;
  v_link text;
  v_single text;
  v_id uuid := p_id;
  v_org uuid;
  v_child_row jsonb;
  v_index integer := 0;
begin
  case p_kind
    when 'work_order' then
      v_parent := 'work_orders'; v_child := 'work_order_items'; v_link := 'work_order_id';
    when 'incident' then
      v_parent := 'incidents'; v_child := 'incident_parties'; v_link := 'incident_id';
      v_single := 'insurance_claims';
    when 'inspection_template' then
      v_parent := 'inspection_templates'; v_child := 'inspection_template_items';
      v_link := 'template_id';
    else
      raise exception 'unknown kind %', p_kind using errcode = '22023';
  end case;

  if v_id is null then
    v_id := public.fleet_save_insert(v_parent, p_row);
  else
    perform public.fleet_save_update(v_parent, v_id, p_row);
  end if;
  execute format('select org_id from public.%I where id = $1', v_parent) into v_org using v_id;

  if p_children is not null then
    execute format('delete from public.%I where %I = $1', v_child, v_link) using v_id;
    for v_child_row in select value from jsonb_array_elements(p_children) loop
      v_child_row := (v_child_row - 'id')
        || jsonb_build_object('org_id', v_org, v_link, v_id)
        || case when exists (select 1 from information_schema.columns
                              where table_schema = 'public' and table_name = v_child
                                and column_name = 'sort_order')
                then jsonb_build_object('sort_order', v_index) else '{}'::jsonb end;
      perform public.fleet_save_insert(v_child, v_child_row);
      v_index := v_index + 1;
    end loop;
  end if;

  if p_single is not null and v_single is not null then
    if nullif(p_single->>'id', '') is null then
      perform public.fleet_save_insert(v_single,
        (p_single - 'id') || jsonb_build_object('org_id', v_org, v_link, v_id));
    else
      perform public.fleet_save_update(v_single, (p_single->>'id')::uuid, p_single - 'id' - v_link - 'org_id');
    end if;
  end if;
  return v_id;
end;
$$;

revoke all on function public.fleet_save_columns(text, jsonb) from public, anon;
revoke all on function public.fleet_save_insert(text, jsonb) from public, anon;
revoke all on function public.fleet_save_update(text, uuid, jsonb) from public, anon;
revoke all on function public.fleet_save(text, uuid, jsonb, jsonb, jsonb) from public, anon;
grant execute on function public.fleet_save_columns(text, jsonb) to authenticated;
grant execute on function public.fleet_save_insert(text, jsonb) to authenticated;
grant execute on function public.fleet_save_update(text, uuid, jsonb) to authenticated;
grant execute on function public.fleet_save(text, uuid, jsonb, jsonb, jsonb) to authenticated;

commit;

insert into vf_meta.ui_migrations (name) values ('20261114130000_fleet_save.sql') on conflict do nothing;
\endif

-- ─── 20261114140000_vehicle_archive.sql
select exists (select 1 from vf_meta.ui_migrations where name = '20261114140000_vehicle_archive.sql') as vf_done \gset
\if :vf_done
\echo 'Already applied: 20261114140000_vehicle_archive.sql'
\else
\echo 'Applying: 20261114140000_vehicle_archive.sql'
-- viper fleet: a vehicle deleted in Traccar stays in the fleet database as archived (ADM-05).
-- Idempotent. Its work orders, documents, incidents and costs keep their vehicle; lists of live
-- vehicles come from Traccar, so an archived one simply no longer appears there.

begin;

alter table public.vehicles add column if not exists archived_at timestamptz;

comment on column public.vehicles.archived_at is
  'Set when the Traccar device was deleted; the history stays (ADM-05).';

commit;

insert into vf_meta.ui_migrations (name) values ('20261114140000_vehicle_archive.sql') on conflict do nothing;
