-- ─── 20261115140000_driver_write_limits.sql
select exists (select 1 from vf_meta.ui_migrations where name = '20261115140000_driver_write_limits.sql') as vf_done \gset
\if :vf_done
\echo 'Already applied: 20261115140000_driver_write_limits.sql'
\else
\echo 'Applying: 20261115140000_driver_write_limits.sql'
-- viper fleet: what a driver may write (SEC-14). Idempotent.
--
-- A driver adds incidents and inspections but does not rewrite or delete them; who reported or
-- created a row is set here from auth.uid(), not by the browser. On a dispatch job a driver may
-- change only the status (along the legal steps: assigned -> en_route -> arrived -> done or
-- failed), the notes and the proof of delivery; a cancelled or finished job stays as it is.

begin;

-- 1. Incidents and inspections: insert only, for drivers.
do $$
declare
  spec text[];
  specs text[][] := array[
    ['inspections', 'inspections.write', '(created_by = auth.uid() or driver_id = public.my_driver_id())'],
    ['incidents', 'incidents.write', '(reported_by = auth.uid() or driver_id = public.my_driver_id())']
  ];
begin
  foreach spec slice 1 in array specs loop
    execute format('drop policy if exists %I on public.%I', spec[1] || '_write', spec[1]);
    -- Managers: everything, as before.
    execute format(
      'create policy %I on public.%I for all using (org_id = public.current_org_id() and public.has_permission(%L) and not public.is_driver_role()) with check (org_id = public.current_org_id() and public.has_permission(%L) and not public.is_driver_role())',
      spec[1] || '_write', spec[1], spec[2], spec[2]);
    execute format('drop policy if exists %I on public.%I', spec[1] || '_driver_insert', spec[1]);
    execute format(
      'create policy %I on public.%I for insert with check (org_id = public.current_org_id() and public.has_permission(%L) and public.is_driver_role() and %s)',
      spec[1] || '_driver_insert', spec[1], spec[2], spec[3]);
  end loop;
end $$;

-- The author of a row is whoever is signed in.
create or replace function public.set_row_author()
returns trigger
language plpgsql
set search_path to 'public'
as $$
begin
  if auth.uid() is not null then
    if tg_table_name = 'incidents' then
      new.reported_by := auth.uid();
    else
      new.created_by := auth.uid();
    end if;
  end if;
  return new;
end;
$$;

drop trigger if exists incidents_author on public.incidents;
create trigger incidents_author before insert on public.incidents
  for each row execute function public.set_row_author();
drop trigger if exists inspections_author on public.inspections;
create trigger inspections_author before insert on public.inspections
  for each row execute function public.set_row_author();

-- 2. Dispatch jobs: a driver changes only these columns, along legal steps. The trigger's name
--    makes it run before the other triggers of the table, on what the driver sent.
create or replace function public.dispatch_driver_guard()
returns trigger
language plpgsql
set search_path to 'public'
as $$
declare
  allowed text[] := array['status', 'notes', 'proof_name', 'proof_photo_path',
                          'proof_signature_path', 'started_at', 'arrived_at', 'completed_at'];
  changed text;
begin
  -- Only the driver's own writes: the database's functions (security definer, e.g. closing the
  -- tracking link when private mode starts) run as their owner and are not limited here.
  if current_user <> 'authenticated' or not public.is_driver_role() then
    return new;
  end if;
  for changed in
    select key from jsonb_each(to_jsonb(new))
     where to_jsonb(new) -> key is distinct from to_jsonb(old) -> key
  loop
    if not changed = any(allowed) then
      raise exception 'a driver cannot change %', changed using errcode = '42501';
    end if;
  end loop;
  if new.status is distinct from old.status and not (
       (old.status in ('planned', 'assigned') and new.status = 'en_route')
    or (old.status = 'en_route' and new.status in ('arrived', 'done', 'failed'))
    or (old.status = 'arrived' and new.status in ('done', 'failed'))
  ) then
    raise exception 'a job cannot go from % to %', old.status, new.status using errcode = '42501';
  end if;
  return new;
end;
$$;

drop trigger if exists dispatch_jobs_a_driver_guard on public.dispatch_jobs;
create trigger dispatch_jobs_a_driver_guard before update on public.dispatch_jobs
  for each row execute function public.dispatch_driver_guard();

commit;

insert into vf_meta.ui_migrations (name) values ('20261115140000_driver_write_limits.sql') on conflict do nothing;
\endif

-- ─── 20261115150000_file_limits.sql
select exists (select 1 from vf_meta.ui_migrations where name = '20261115150000_file_limits.sql') as vf_done \gset
\if :vf_done
\echo 'Already applied: 20261115150000_file_limits.sql'
\else
\echo 'Applying: 20261115150000_file_limits.sql'
-- viper fleet: what may be uploaded (SEC-17). Idempotent.
--
-- Both private buckets take only documents and photos (PDF, JPEG, PNG, WebP, HEIC, Office files,
-- and tachograph files as plain bytes), up to 15 MB each. HTML, SVG and scripts are refused by
-- Storage itself, whatever the browser says the file is. The app also re-encodes photos before
-- upload (which drops their GPS position) and opens non-images as downloads.

begin;

do $$
begin
  if exists (select 1 from information_schema.columns
              where table_schema = 'storage' and table_name = 'buckets'
                and column_name = 'allowed_mime_types') then
    update storage.buckets
       set file_size_limit = 15 * 1024 * 1024,
           allowed_mime_types = array[
             'application/pdf', 'image/jpeg', 'image/png', 'image/webp', 'image/heic', 'image/heif',
             'application/msword',
             'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
             'application/vnd.ms-excel',
             'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
             'text/csv',
             -- Tachograph downloads (.ddd, .tgd) have no type of their own; Storage serves them
             -- as a download, never as a page.
             'application/octet-stream']
     where id in ('fleet-files', 'documents');
  end if;
end $$;

commit;

insert into vf_meta.ui_migrations (name) values ('20261115150000_file_limits.sql') on conflict do nothing;
\endif

-- ─── 20261115160000_queue_expiry.sql
select exists (select 1 from vf_meta.ui_migrations where name = '20261115160000_queue_expiry.sql') as vf_done \gset
\if :vf_done
\echo 'Already applied: 20261115160000_queue_expiry.sql'
\else
\echo 'Applying: 20261115160000_queue_expiry.sql'
-- viper fleet: the message queue does not keep old alerts for later (SEC-18). Idempotent.
--
-- A message waits at most two days. Whatever was queued before a channel was connected, and is
-- older than that, is skipped as expired instead of arriving all at once on the day a provider is
-- set up. Finished messages are kept 180 days, then removed.

begin;

alter table public.notification_deliveries
  add column if not exists expires_at timestamptz;
update public.notification_deliveries
   set expires_at = created_at + interval '2 days'
 where expires_at is null;
alter table public.notification_deliveries
  alter column expires_at set default now() + interval '2 days';

create or replace function public.messaging_expire()
returns integer
language sql
security definer
set search_path to 'public'
as $$
  with expired as (
    update public.notification_deliveries
       set status = 'skipped', last_error = 'expired'
     where status = 'queued' and expires_at is not null and expires_at < now()
    returning 1
  )
  select count(*)::integer from expired;
$$;

create or replace function public.messaging_cleanup()
returns integer
language sql
security definer
set search_path to 'public'
as $$
  with removed as (
    delete from public.notification_deliveries
     where status in ('sent', 'failed', 'skipped') and created_at < now() - interval '180 days'
    returning 1
  )
  select count(*)::integer from removed;
$$;

revoke all on function public.messaging_expire() from public, anon, authenticated;
revoke all on function public.messaging_cleanup() from public, anon, authenticated;

commit;

-- Every minute the expired go first; every night the old are removed.
do $$
begin
  if exists (select 1 from pg_available_extensions where name = 'pg_net') then
    perform cron.unschedule(jobid) from cron.job where jobname = 'vf_messaging';
    perform cron.schedule('vf_messaging', '* * * * *',
      'select public.messaging_expire(); select public.messaging_collect(); select public.messaging_dispatch();');
  end if;
  perform cron.unschedule(jobid) from cron.job where jobname = 'vf_messaging_cleanup';
  perform cron.schedule('vf_messaging_cleanup', '20 3 * * *', 'select public.messaging_cleanup()');
end;
$$;

insert into vf_meta.ui_migrations (name) values ('20261115160000_queue_expiry.sql') on conflict do nothing;
\endif

-- ─── 20261115170000_impersonation.sql
select exists (select 1 from vf_meta.ui_migrations where name = '20261115170000_impersonation.sql') as vf_done \gset
\if :vf_done
\echo 'Already applied: 20261115170000_impersonation.sql'
\else
\echo 'Applying: 20261115170000_impersonation.sql'
-- viper fleet: "log in as" another user is recorded (SEC-13). Idempotent.
--
-- The app asks for a reason and records the start and the end in the audit log, with who did it.
-- Every audit row written while impersonating carries impersonated_by, read from the fleet JWT
-- claim of that name (the traccar-auth function adds it when the Traccar session was switched).

begin;

alter table public.audit_log add column if not exists impersonated_by text;

create or replace function public.audit_log_impersonation()
returns trigger
language plpgsql
set search_path to 'public'
as $$
declare
  claims jsonb := nullif(current_setting('request.jwt.claims', true), '')::jsonb;
begin
  if new.impersonated_by is null and claims ? 'impersonated_by' then
    new.impersonated_by := claims ->> 'impersonated_by';
  end if;
  return new;
end;
$$;

drop trigger if exists audit_log_impersonation on public.audit_log;
create trigger audit_log_impersonation before insert on public.audit_log
  for each row execute function public.audit_log_impersonation();

-- p_event: 'start' (by the one who switches, before the switch) or 'end' (by the session that
-- was switched to, when it goes back).
create or replace function public.record_impersonation(
  p_event text, p_target_user integer, p_target_name text, p_by_name text, p_reason text)
returns void
language plpgsql
security definer
set search_path to 'public'
as $$
begin
  if auth.uid() is null then
    raise exception 'not signed in' using errcode = '42501';
  end if;
  if p_event not in ('start', 'end') then
    raise exception 'unknown event' using errcode = '22023';
  end if;
  if p_event = 'start' and length(trim(coalesce(p_reason, ''))) < 5 then
    raise exception 'a reason is needed' using errcode = '22023';
  end if;
  insert into public.audit_log (org_id, user_id, action, table_name, row_id, new_data)
  values (public.current_org_id(), auth.uid(), 'impersonate_' || p_event, 'traccar_users',
          p_target_user::text,
          jsonb_build_object('target', left(p_target_name, 200), 'by', left(p_by_name, 200),
                             'reason', left(p_reason, 500)));
end;
$$;

revoke all on function public.record_impersonation(text, integer, text, text, text) from public, anon;
grant execute on function public.record_impersonation(text, integer, text, text, text) to authenticated;

commit;

