\endif

-- ─── 20261116250000_market_prices.sql
select exists (select 1 from vf_meta.ui_migrations where name = '20261116250000_market_prices.sql') as vf_done \gset
\if :vf_done
\echo 'Already applied: 20261116250000_market_prices.sql'
\else
\echo 'Applying: 20261116250000_market_prices.sql'
-- viper fleet: what a garage job usually costs, across fleets (AI-08). Idempotent.
--
-- For a work order's lines: the median unit price of the same line (compared loosely, without
-- case and punctuation) in done work orders of the last 12 months, across the fleets that agreed
-- to the comparison (benchmark_opt_in, AI-09; give to get). Only when at least 5 other fleets
-- have that line; never a fleet's name or its own prices.

begin;

create or replace function public.normalize_item(p_text text)
returns text
language sql
immutable
as $$
  select trim(regexp_replace(regexp_replace(lower(coalesce(p_text, '')), '["''״׳`]', '', 'g'),
                             '[^[:alnum:]]+', ' ', 'g'))
$$;

create or replace function public.market_prices(p_descriptions text[], p_min_fleets integer default 5)
returns table (description text, median numeric, fleets integer)
language plpgsql
stable
security definer
set search_path to 'public'
as $$
declare
  me uuid := public.current_org_id();
begin
  if not (public.has_permission('maintenance.read') or public.has_permission('costs.read')) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if not coalesce((select benchmark_opt_in from public.organizations where id = me), false) then
    return;
  end if;
  return query
    with wanted as (
      select distinct d as description, public.normalize_item(d) as key
        from unnest(coalesce(p_descriptions, '{}')) d
       where length(public.normalize_item(d)) >= 3
       limit 100
    ),
    lines as (
      select public.normalize_item(i.description) as key, i.org_id, i.unit_price
        from public.work_order_items i
        join public.work_orders w on w.id = i.work_order_id and w.status = 'done'
        join public.organizations o on o.id = i.org_id and o.benchmark_opt_in
       where i.org_id <> me
         and coalesce(w.closed_at, w.opened_at) >= now() - interval '12 months'
         and i.unit_price > 0
    )
    select wanted.description,
           round(percentile_cont(0.5) within group (order by l.unit_price)::numeric, 2),
           count(distinct l.org_id)::integer
      from wanted join lines l on l.key = wanted.key
     group by wanted.description
    having count(distinct l.org_id) >= greatest(p_min_fleets, 5);
end;
$$;

revoke all on function public.market_prices(text[], integer) from public, anon;
grant execute on function public.market_prices(text[], integer) to authenticated;

commit;

insert into vf_meta.ui_migrations (name) values ('20261116250000_market_prices.sql') on conflict do nothing;
\endif

-- ─── 20261116260000_driver_fueling.sql
select exists (select 1 from vf_meta.ui_migrations where name = '20261116260000_driver_fueling.sql') as vf_done \gset
\if :vf_done
\echo 'Already applied: 20261116260000_driver_fueling.sql'
\else
\echo 'Applying: 20261116260000_driver_fueling.sql'
-- ADM-18: a driver records a fueling (with the receipt's photo) from the driver portal, on the
-- vehicle assigned to them now. Managers keep writing fuel rows with costs.write; a driver has
-- no costs permission, so the row goes in through one function that checks who and which car.
begin;

alter table public.fuel_transactions add column if not exists receipt_path text;

alter table public.fuel_transactions drop constraint if exists fuel_transactions_source_check;
alter table public.fuel_transactions
  add constraint fuel_transactions_source_check check (source in ('import', 'manual', 'driver'));

-- Receipts live under <org_id>/fuel/...: written with costs.write, or by a driver (their own
-- fueling, through the portal); read with the costs permissions.
create or replace function public.fleet_file_permission(p_name text, p_write boolean)
returns boolean
language sql
stable
security definer
set search_path to 'public'
as $$
  select (storage.foldername(p_name))[1] = public.current_org_id()::text
     and case (storage.foldername(p_name))[2]
           when 'work-orders' then public.has_permission(case when p_write then 'maintenance.write' else 'maintenance.read' end)
           when 'incidents' then public.has_permission(case when p_write then 'incidents.write' else 'incidents.read' end)
           when 'inspections' then public.has_permission(case when p_write then 'inspections.write' else 'inspections.read' end)
           when 'expenses' then public.has_permission(case when p_write then 'costs.write' else 'costs.read' end)
           when 'fuel' then case
             when p_write then public.has_permission('costs.write')
                            or (public.is_driver_role() and public.my_driver_id() is not null)
             else public.has_permission('costs.read') or public.has_permission('costs.write')
           end
           when 'safety' then public.has_permission(case when p_write then 'safety.write' else 'safety.read' end)
           when 'procedures' then case when p_write then public.has_permission('safety.write') else true end
           -- Drivers upload proof of delivery for their own jobs with dispatch.read.
           when 'dispatch' then case
             when p_write then public.has_permission('dispatch.write')
                            or (public.is_driver_role() and public.has_permission('dispatch.read'))
             else public.has_permission('dispatch.read') or public.has_permission('dispatch.write')
           end
           else false
         end;
$$;

-- The driver's fueling, on the vehicle assigned to them at this moment. `p_id` is made in the
-- phone, so a report sent twice from the offline queue is saved once.
create or replace function public.driver_report_fueling(
  p_id uuid,
  p_occurred_at timestamptz,
  p_total numeric,
  p_liters numeric default null,
  p_odometer numeric default null,
  p_station text default null,
  p_receipt_path text default null
)
returns uuid
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  v_org uuid := public.current_org_id();
  v_driver uuid := public.my_driver_id();
  v_vehicle uuid;
begin
  if v_driver is null then
    raise exception 'not a driver' using errcode = '42501';
  end if;
  select a.vehicle_id into v_vehicle
    from public.vehicle_driver_assignments a
   where a.driver_id = v_driver and a.org_id = v_org
     -- The vehicle held when the fueling happened: a report sent later from the phone's outbox,
     -- after the driver changed vehicles, still goes to the vehicle that was fueled.
     and a.starts_at <= p_occurred_at and (a.ends_at is null or a.ends_at > p_occurred_at)
   order by a.starts_at desc
   limit 1;
  if v_vehicle is null then
    raise exception 'no vehicle assigned' using errcode = 'P0002';
  end if;
  if p_total is null or p_total <= 0 or (p_liters is not null and p_liters <= 0) then
    raise exception 'amount must be positive' using errcode = '22023';
  end if;
  if p_occurred_at > now() + interval '1 hour' or p_occurred_at < now() - interval '30 days' then
    raise exception 'fueling time out of range' using errcode = '22023';
  end if;
  if p_receipt_path is not null and p_receipt_path not like v_org::text || '/fuel/%' then
    raise exception 'receipt outside the organization' using errcode = '42501';
  end if;
  insert into public.fuel_transactions (
    id, org_id, vehicle_id, driver_id, occurred_at, total, liters, unit_price,
    odometer_reported, station, receipt_path, source, created_by
  ) values (
    p_id, v_org, v_vehicle, v_driver, p_occurred_at, p_total, p_liters,
    case when p_liters > 0 then round(p_total / p_liters, 3) end,
    p_odometer, nullif(trim(p_station), ''), p_receipt_path, 'driver', auth.uid()
  )
  on conflict (id) do nothing;
  return p_id;
end;
$$;

revoke all on function public.driver_report_fueling(uuid, timestamptz, numeric, numeric, numeric, text, text) from public;
grant execute on function public.driver_report_fueling(uuid, timestamptz, numeric, numeric, numeric, text, text) to authenticated;

commit;

insert into vf_meta.ui_migrations (name) values ('20261116260000_driver_fueling.sql') on conflict do nothing;
\endif

-- ─── 20261116270000_checkin_source.sql
select exists (select 1 from vf_meta.ui_migrations where name = '20261116270000_checkin_source.sql') as vf_done \gset
\if :vf_done
\echo 'Already applied: 20261116270000_checkin_source.sql'
\else
\echo 'Applying: 20261116270000_checkin_source.sql'
-- viper fleet: a driver's check-in starts the working day (OPS-05). Idempotent.
--
-- An assignment says where it came from: 'checkin' when the driver scanned the vehicle's QR
-- (driver_check_in), null otherwise (a manager's assignment). The work hours report takes the
-- first check-in of a day as the start of that day, when it comes before the first ignition.

begin;

alter table public.vehicle_driver_assignments add column if not exists source text;
alter table public.vehicle_driver_assignments drop constraint if exists vehicle_driver_assignments_source_check;
alter table public.vehicle_driver_assignments
  add constraint vehicle_driver_assignments_source_check check (source is null or source in ('checkin'));

create or replace function public.driver_check_in(p_device integer, p_code text)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  v_driver uuid := public.my_driver_id();
  v_org uuid := public.current_org_id();
  v_vehicle public.vehicles;
begin
  if v_driver is null then
    raise exception 'not a driver' using errcode = '42501';
  end if;
  select * into v_vehicle from public.vehicles
   where org_id = v_org and traccar_device_id = p_device
     and checkin_code is not null and checkin_code = p_code;
  if v_vehicle.id is null then
    raise exception 'unknown vehicle or wrong code' using errcode = '42501';
  end if;
  update public.vehicle_driver_assignments
     set ends_at = now()
   where org_id = v_org and ends_at is null
     and (vehicle_id = v_vehicle.id or driver_id = v_driver);
  insert into public.vehicle_driver_assignments (org_id, vehicle_id, driver_id, starts_at, source)
  values (v_org, v_vehicle.id, v_driver, now(), 'checkin');
  return jsonb_build_object('vehicle_id', v_vehicle.id, 'plate_number', v_vehicle.plate_number,
                            'traccar_device_id', v_vehicle.traccar_device_id);
end;
$$;

revoke all on function public.driver_check_in(integer, text) from public, anon;
grant execute on function public.driver_check_in(integer, text) to authenticated;

commit;

insert into vf_meta.ui_migrations (name) values ('20261116270000_checkin_source.sql') on conflict do nothing;
\endif

-- ─── 20261117100000_missed_check_alerts.sql
select exists (select 1 from vf_meta.ui_migrations where name = '20261117100000_missed_check_alerts.sql') as vf_done \gset
\if :vf_done
\echo 'Already applied: 20261117100000_missed_check_alerts.sql'
\else
\echo 'Applying: 20261117100000_missed_check_alerts.sql'
-- viper fleet: a message to the manager when a vehicle went out without its morning check (ADM-31).
-- Idempotent.
--
-- The checks page already lists the vehicles that drove today without a check, but only for whoever
-- opens it. This runs on the server, every 10 minutes:
-- * Only in organizations with an active daily checklist (inspection_templates.frequency 'daily').
-- * A vehicle counts as "out" from the moment a driver took it today: a check-in (QR) or an
--   assignment that started today, in the organization's time zone (privacy_policies.timezone,
--   Asia/Jerusalem by default). Driving itself is in Traccar, which this database cannot read.
-- * 30 minutes after that, if the vehicle has no inspection since the start of the day, one
--   message per vehicle per day goes to every active recipient that chose 'missed_check'.

begin;

create table if not exists public.missed_check_alerts (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.organizations (id) on delete cascade,
  vehicle_id uuid not null references public.vehicles (id) on delete cascade,
  driver_id uuid references public.drivers (id) on delete set null,
  day date not null,
  taken_at timestamptz not null,
  created_at timestamptz not null default now(),
  unique (vehicle_id, day)
);

alter table public.missed_check_alerts enable row level security;

drop policy if exists missed_check_alerts_read on public.missed_check_alerts;
create policy missed_check_alerts_read on public.missed_check_alerts
  for select to authenticated
  using (org_id = (select public.current_org_id()) and (select public.has_permission('inspections.read')));

revoke all on public.missed_check_alerts from anon;
revoke insert, update, delete on public.missed_check_alerts from authenticated;
grant select on public.missed_check_alerts to authenticated;

create index if not exists missed_check_alerts_org_day on public.missed_check_alerts (org_id, day desc);

create or replace function public.generate_missed_check_alerts(
  p_now timestamptz default now(),
  p_grace interval default interval '30 minutes'
)
returns integer
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  created integer := 0;
  rec record;
  alert_id uuid;
  label text;
begin
  for rec in
    with orgs as (
      select o.id as org_id, coalesce(p.timezone, 'Asia/Jerusalem') as tz
        from public.organizations o
        left join public.privacy_policies p on p.org_id = o.id
       where exists (select 1 from public.inspection_templates t
                      where t.org_id = o.id and t.active and t.frequency = 'daily')
    ),
    taken as (
      -- The first time each vehicle was taken today.
      select distinct on (a.vehicle_id)
             a.org_id, a.vehicle_id, a.driver_id, a.starts_at, o.tz,
             (p_now at time zone o.tz)::date as day
        from public.vehicle_driver_assignments a
        join orgs o on o.org_id = a.org_id
       where (a.starts_at at time zone o.tz)::date = (p_now at time zone o.tz)::date
         and a.starts_at <= p_now - p_grace
       order by a.vehicle_id, a.starts_at
    )
    select k.*, v.plate_number, v.name as vehicle_name, d.full_name
      from taken k
      join public.vehicles v on v.id = k.vehicle_id
      left join public.drivers d on d.id = k.driver_id
     where not exists (
             select 1 from public.inspections i
              where i.vehicle_id = k.vehicle_id
                and i.started_at >= (k.day::timestamp at time zone k.tz))
  loop
    insert into public.missed_check_alerts (org_id, vehicle_id, driver_id, day, taken_at)
    values (rec.org_id, rec.vehicle_id, rec.driver_id, rec.day, rec.starts_at)
    on conflict (vehicle_id, day) do nothing
    returning id into alert_id;

    if alert_id is null then
      continue;
    end if;
    created := created + 1;

    label := format('הרכב %s יצא היום בלי בדיקת בוקר%s. נלקח ב-%s.',
                    coalesce(rec.plate_number, rec.vehicle_name, ''),
                    case when rec.full_name is not null then format(' (נהג: %s)', rec.full_name) else '' end,
                    to_char(rec.starts_at at time zone rec.tz, 'HH24:MI'));

    insert into public.notification_deliveries
      (org_id, kind, channel, recipient_id, address, subject, body, payload)
    select rec.org_id, 'missed_check', r.channel, r.id, r.address,
           format('בדיקת בוקר חסרה: %s', coalesce(rec.plate_number, rec.vehicle_name, '')), label,
           jsonb_build_object('vehicle_id', rec.vehicle_id, 'driver_id', rec.driver_id,
                              'day', rec.day, 'taken_at', rec.starts_at, 'alert_id', alert_id)
      from public.alert_recipients r
     where r.org_id = rec.org_id and r.active
       and 'missed_check' = any (r.kinds);
  end loop;
  return created;
end;
$$;

revoke all on function public.generate_missed_check_alerts(timestamptz, interval) from public, anon, authenticated;

commit;

-- Every 10 minutes. Where pg_cron is missing (a local test database), nothing is scheduled.
do $$
begin
  if exists (select 1 from pg_namespace where nspname = 'cron')
     and exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
                  where n.nspname = 'cron' and p.proname = 'schedule') then
    perform cron.unschedule(jobid) from cron.job where jobname = 'vf_missed_checks';
    perform cron.schedule('vf_missed_checks', '*/10 * * * *',
                          'select public.generate_missed_check_alerts();');
  else
    raise notice 'pg_cron is not available: missed checks are not alerted';
  end if;
end;
$$;

insert into vf_meta.ui_migrations (name) values ('20261117100000_missed_check_alerts.sql') on conflict do nothing;
\endif

-- ─── 20261117110000_driver_disputes.sql
select exists (select 1 from vf_meta.ui_migrations where name = '20261117110000_driver_disputes.sql') as vf_done \gset
\if :vf_done
\echo 'Already applied: 20261117110000_driver_disputes.sql'
\else
\echo 'Applying: 20261117110000_driver_disputes.sql'
-- viper fleet: the driver sees their own safety score and can disagree with an event
-- (SAF-05, SEC-23). Idempotent.
--
-- * driver_my_periods(): the periods the signed-in driver had each vehicle (by Traccar id),
--   including vehicles they no longer have, so the driver portal attributes trips and events to
--   them and to nobody else.
-- * safety_driver_dispute(): "I disagree" on one event of their own (a period of theirs covers
--   it), once, with a reason. The event goes back to the safety inbox, marked as disputed.
-- * The driver reads the reviews of the events they disputed (and, as before, those sent to
--   them for a self-review), with the manager's answer.
-- * When the manager decides a disputed event, dismissing it accepts the dispute (the event
--   leaves the score) and any other decision rejects it.

begin;

alter table public.safety_event_reviews
  add column if not exists dispute_reason text,
  add column if not exists dispute_note text,
  add column if not exists disputed_at timestamptz,
  add column if not exists dispute_result text,
  add column if not exists dispute_resolved_at timestamptz;

alter table public.safety_event_reviews drop constraint if exists safety_event_reviews_dispute_reason_check;
alter table public.safety_event_reviews add constraint safety_event_reviews_dispute_reason_check
  check (dispute_reason is null or dispute_reason in ('not_me', 'device_error', 'road_conditions', 'other'));
alter table public.safety_event_reviews drop constraint if exists safety_event_reviews_dispute_result_check;
alter table public.safety_event_reviews add constraint safety_event_reviews_dispute_result_check
  check (dispute_result is null or dispute_result in ('accepted', 'rejected'));
alter table public.safety_event_reviews drop constraint if exists safety_event_reviews_dispute_note_check;
alter table public.safety_event_reviews add constraint safety_event_reviews_dispute_note_check
  check (dispute_note is null or length(dispute_note) <= 500);

create index if not exists safety_event_reviews_disputed_idx
  on public.safety_event_reviews (org_id, disputed_at) where disputed_at is not null;

drop policy if exists safety_event_reviews_select on public.safety_event_reviews;
create policy safety_event_reviews_select on public.safety_event_reviews for select
  using (org_id = (select public.current_org_id())
         and ((select public.has_permission('safety.read'))
              or ((self_review or disputed_at is not null)
                  and driver_id = (select public.my_driver_id()))));

-- The manager's decision on a disputed event answers the dispute.
create or replace function public.safety_dispute_answer()
returns trigger
language plpgsql
set search_path to 'public'
as $$
begin
  if new.disputed_at is not null and new.status is distinct from old.status then
    if new.status = 'pending' then
      new.dispute_result := null;
      new.dispute_resolved_at := null;
    else
      new.dispute_result := case when new.status = 'dismissed' then 'accepted' else 'rejected' end;
      new.dispute_resolved_at := now();
    end if;
  end if;
  return new;
end;
$$;

drop trigger if exists safety_event_reviews_dispute on public.safety_event_reviews;
create trigger safety_event_reviews_dispute before update on public.safety_event_reviews
  for each row execute function public.safety_dispute_answer();

create or replace function public.driver_my_periods(p_from timestamptz default now() - interval '90 days')
returns table (traccar_device_id integer, plate_number text, starts_at timestamptz, ends_at timestamptz)
language sql
stable
security definer
set search_path to 'public'
as $$
  select v.traccar_device_id, v.plate_number, a.starts_at, a.ends_at
    from public.vehicle_driver_assignments a
    join public.vehicles v on v.id = a.vehicle_id
   where a.driver_id = public.my_driver_id()
     and a.org_id = public.current_org_id()
     and (a.ends_at is null or a.ends_at > p_from)
   order by a.starts_at;
$$;

revoke all on function public.driver_my_periods(timestamptz) from public, anon;
grant execute on function public.driver_my_periods(timestamptz) to authenticated;

create or replace function public.safety_driver_dispute(
  p_event bigint,
  p_device integer,
  p_category text,
  p_occurred_at timestamptz,
  p_reason text,
  p_note text default null
)
returns void
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  v_driver uuid := public.my_driver_id();
  v_org uuid := public.current_org_id();
  v_review public.safety_event_reviews;
begin
  if v_driver is null then
    raise exception 'not a driver' using errcode = '42501';
  end if;
  if p_reason is null or p_reason not in ('not_me', 'device_error', 'road_conditions', 'other') then
    raise exception 'unknown reason' using errcode = '22023';
  end if;
  if p_occurred_at > now() + interval '5 minutes' or p_occurred_at < now() - interval '90 days' then
    raise exception 'too old to dispute' using errcode = '22023';
  end if;
  -- Only an event in a period the driver had the vehicle.
  if not exists (
    select 1 from public.vehicle_driver_assignments a
      join public.vehicles v on v.id = a.vehicle_id
     where a.driver_id = v_driver and a.org_id = v_org and v.traccar_device_id = p_device
       and a.starts_at <= p_occurred_at and (a.ends_at is null or a.ends_at > p_occurred_at)
  ) then
    raise exception 'not your event' using errcode = '42501';
  end if;

  select * into v_review from public.safety_event_reviews
   where org_id = v_org and traccar_event_id = p_event;
  if v_review.id is not null then
    if v_review.traccar_device_id <> p_device
       or (v_review.driver_id is not null and v_review.driver_id <> v_driver) then
      raise exception 'not your event' using errcode = '42501';
    end if;
    if v_review.disputed_at is not null then
      raise exception 'already disputed' using errcode = '42501';
    end if;
    update public.safety_event_reviews
       set driver_id = v_driver, dispute_reason = p_reason, dispute_note = nullif(trim(p_note), ''),
           disputed_at = now(), status = 'pending', dispute_result = null, dispute_resolved_at = null
     where id = v_review.id;
  else
    insert into public.safety_event_reviews
      (org_id, traccar_event_id, traccar_device_id, driver_id, category, occurred_at,
       dispute_reason, dispute_note, disputed_at)
    values (v_org, p_event, p_device, v_driver, left(p_category, 40), p_occurred_at,
            p_reason, nullif(trim(p_note), ''), now());
  end if;
end;
$$;

revoke all on function public.safety_driver_dispute(bigint, integer, text, timestamptz, text, text) from public, anon;
grant execute on function public.safety_driver_dispute(bigint, integer, text, timestamptz, text, text) to authenticated;

commit;

